const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nwPennsylvania = ee.Geometry.Polygon([
    [[-80.5, 42.0], [-79.0, 42.0], [-79.0, 41.0], [-80.5, 41.0], [-80.5, 42.0]]
  ]);

  const date1 = '2020-02-22';
  const date2 = '2020-03-01';

  // 2. Data Acquisition - MODIS Snow Cover
  const modisSnow = ee.ImageCollection('MODIS/006/MOD10A1')
    .select('NDSI_Snow_Cover');

  const snowFeb22 = modisSnow.filterDate(date1, ee.Date(date1).advance(1, 'day'));
  const snowMar1 = modisSnow.filterDate(date2, ee.Date(date2).advance(1, 'day'));

  // Check collection sizes
  const countFeb22 = snowFeb22.size().getInfo();
  const countMar1 = snowMar1.size().getInfo();

  console.log(`Feb 22 Images: ${countFeb22}, Mar 1 Images: ${countMar1}`);

  if (countFeb22 === 0 || countMar1 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get single images for each date
  const imgFeb22 = snowFeb22.first();
  const imgMar1 = snowMar1.first();

  // 3. Processing - Calculate snow cover percentage
  const scale = 1000;

  const statsFeb22 = imgFeb22.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: nwPennsylvania,
    scale: scale,
    maxPixels: 1e9
  });

  const statsMar1 = imgMar1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: nwPennsylvania,
    scale: scale,
    maxPixels: 1e9
  });

  const meanFeb22 = statsFeb22.get('NDSI_Snow_Cover_mean').getInfo();
  const countPixelsFeb22 = statsFeb22.get('NDSI_Snow_Cover_count').getInfo();
  const meanMar1 = statsMar1.get('NDSI_Snow_Cover_mean').getInfo();
  const countPixelsMar1 = statsMar1.get('NDSI_Snow_Cover_count').getInfo();

  console.log(`Feb 22: Snow Cover ${meanFeb22?.toFixed(2) || 'N/A'}%, Pixels: ${countPixelsFeb22}`);
  console.log(`Mar 1: Snow Cover ${meanMar1?.toFixed(2) || 'N/A'}%, Pixels: ${countPixelsMar1}`);

  // Check for valid pixels
  if (countPixelsFeb22 === 0 || countPixelsMar1 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (meanFeb22 === null || meanMar1 === null || 
      isNaN(meanFeb22) || isNaN(meanMar1) ||
      meanFeb22 < 0 || meanFeb22 > 100 ||
      meanMar1 < 0 || meanMar1 > 100) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Final comparison
  console.log(`Snow cover change: ${(meanMar1 - meanFeb22).toFixed(2)}%`);

  if (meanMar1 > meanFeb22) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
